import * as THREE from 'three/webgpu';
import { texture, uv, vec2, uniform } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-title';
  group.position.set(0, 3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const atlasIndex = 0;
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const atlasW = 512;
  const atlasH = 320;

  const aspect = rect.w / rect.h;
  const height = 0.6;
  const width = height * aspect;

  const geometry = new THREE.PlaneGeometry(width, height);

  const map = ctx.textureLoader.load('/prism-mock/home/nodes/floating-accent.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const uvScale = vec2(rect.w / atlasW, rect.h / atlasH);
  const uvOffset = vec2(rect.x / atlasW, rect.y / atlasH);
  const uvNode = uv().mul(uvScale).add(uvOffset);

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });
  material.colorNode = texture(map, uvNode);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'sprite-mesh';
  group.add(mesh);

  // Billboard behavior handled per-frame via userData.update, invoked by scene manager if present
  group.userData.update = (camera) => {
    if (camera) {
      mesh.quaternion.copy(camera.quaternion);
    }
  };

  // Text content rendering via font atlas (headline "Journal")
  let textMesh = null;
  if (ctx.fontAtlas && ctx.fontAtlas.createText) {
    textMesh = ctx.fontAtlas.createText({
      text: 'Journal',
      font: 'Lora',
      weight: 400,
      size: 0.34,
      color: config?.visual?.colors?.paper || '#e8ecf2',
    });
    if (textMesh) {
      textMesh.position.set(0, 0, 0.01);
      group.add(textMesh);
    }
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map) map.dispose();
    if (textMesh) {
      group.remove(textMesh);
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
    group.userData.handlers = {};
  };

  return group;
}
